def binomial_coefficient(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result


def binomial_coefficient_recursive(n, k, memo=None):
    if memo is None:
        memo = {}
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if (n, k) in memo:
        return memo[(n, k)]
    memo[(n, k)] = binomial_coefficient_recursive(n - 1, k - 1, memo) + binomial_coefficient_recursive(n - 1, k, memo)
    return memo[(n, k)]


